// vite.config.ts
function criticalScriptPlugin(): Plugin {
  return {
	  name: "critical-script",
    transformIndexHtml: {
        order: "post", // Vite의 모든 처리 후에 실행
        async handler(html) {
            const fs = await import("node:fs/promises");
            const criticalCode = await fs.readFile("./src/page.critical.ts", "utf-8");

            // <head> 다음에 inline script 주입
            return html.replace("<head>", `<head>\n  <script type="module">${criticalCode}</script>`);
        }
    },

    // 개발 서버에서 /api/hero 간단 목
    configureServer(server) {
      server.middlewares.use("/api/hero", async (_req, res) => {
        // 지연/네트워크 왕복을 흉내내고 싶다면 setTimeout으로 100~300ms 정도 지연시켜 보세요.

        setTimeout(() => {
          res.setHeader("Content-Type", "application/json; charset=utf-8");
          res.end(
            JSON.stringify({
              title: "크리티컬 프리페치로 LCP 당겨오기",
              message:
                "이 데이터가 히어로 영역(LCP 후보)을 구성한다고 가정합니다.",
            })
          );
        }, 500);
      });
    },
  };
}

export default defineConfig({
  plugins: [react(), criticalScriptPlugin()],
  server: {
    port: 5173,
  },
});

