// 가장 이른 시점에 실행
(function () {
    try {
        const url = "/api/hero";
        const req = fetch(url, {
            headers: {Accept: "application/json"}
        });

        // 전역 네임스페이스 준비
        window.__boot = {
            promises: new Map(),
            data: new Map()
        };

        // 이미 출발시킨 동일 요청이 있으면 재사용
        if (!window.__boot.promises.has(url)) {
            const p = req
                .then(async r => {
                    if (!r.ok) throw new Error("prefetch failed");
                    const data = await r.clone().json();

                    // 1) 즉시 접근용 동기 캐시
                    window.__boot?.data.set(url, data);

                    // 2) Cache Storage에도 저장(선택)
                    if ("caches" in window) {
                        const c = await caches.open("boot-v1");
                        await c.put(url, r);
                    }
                    return data;
                })
                .catch(e => {
                    // 실패 시 레지스트리에서 제거(다음엔 앱이 직접 fetch)
                    throw e;
                })
                .finally(() => {
                    window.__boot?.promises.delete(url);
                });

            window.__boot?.promises.set(url, p);
        }
    } catch {}
})();

